package pe.manchapp.beta;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public final class PhotoComposeActivity extends Activity {
    private PhotoUi ui;
    private CompositionDocument document;
    private PhotoCompositionView canvas;
    private LinearLayout root,panel,layerRow;
    private TextView save,status,remove,correct;
    private final ArrayList<String> history=new ArrayList<>();
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private boolean busy=false,destroyed=false;
    @Override public void onCreate(Bundle state){super.onCreate(state);ui=new PhotoUi(this);getWindow().setStatusBarColor(PhotoUi.BG);getWindow().setNavigationBarColor(PhotoUi.PANEL);try{document=CompositionDocument.open(this,getIntent().getStringExtra("compositionId"));String selected=state==null?(document.layers().length()==0?"background":document.layers().getJSONObject(0).getString("id")):state.getString("selected","background");if(state!=null&&state.getStringArrayList("history")!=null)history.addAll(state.getStringArrayList("history"));draw(selected);}catch(Exception error){Toast.makeText(this,"No pudimos abrir la composición. Tus fotos anteriores se conservan.",Toast.LENGTH_LONG).show();finish();}}
    private void draw(String selected){
        root=ui.column();root.setBackgroundColor(PhotoUi.BG);setContentView(root);save=ui.button("Listo",true,()->save());save.setTag("compose:save");root.addView(ui.header("Combinar fotos",ui.icon("back","Volver al editor",()->finish()),save));
        canvas=new PhotoCompositionView(this,document,selected,new PhotoCompositionView.Listener(){public void selected(){layers();}public void changed(String before){commit(before);}public void failed(){status.setText("No pudimos mostrar una imagen. Las fotos se conservan.");}});canvas.setTag("compose:canvas");root.addView(canvas,new LinearLayout.LayoutParams(-1,0,1));
        status=ui.text("Arrastra el producto · usa dos dedos para ajustar",12,PhotoUi.MUTED,false);status.setGravity(Gravity.CENTER);status.setPadding(ui.dp(12),0,ui.dp(12),ui.dp(10));status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);root.addView(status);
        panel=ui.column();panel.setPadding(ui.dp(14),ui.dp(10),ui.dp(14),ui.dp(12));panel.setBackground(ui.background(PhotoUi.PANEL,0,20));root.addView(panel);
        HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);layerRow=new LinearLayout(this);scroll.addView(layerRow);ui.add(panel,scroll,0);layers();
        LinearLayout add=new LinearLayout(this);TextView more=ui.button("+ Producto",true,()->pick(false));more.setTag("compose:add");ui.weighted(add,more,false);ui.weighted(add,ui.button("Cambiar fondo",false,()->pick(true)),true);ui.add(panel,add,8);
        LinearLayout controls=new LinearLayout(this);TextView smaller=ui.button("−",false,()->zoom(.85f)),larger=ui.button("+",false,()->zoom(1.18f));smaller.setTextSize(22);larger.setTextSize(22);smaller.setContentDescription("Reducir el elemento seleccionado");larger.setContentDescription("Ampliar el elemento seleccionado");ui.weighted(controls,smaller,false);ui.weighted(controls,larger,false);ui.weighted(controls,ui.button("Centrar",false,()->center()),false);TextView options=ui.button("Más",false,()->options());ui.weighted(controls,options,true);ui.add(panel,controls,8);
        LinearLayout edits=new LinearLayout(this);remove=ui.button("Quitar producto",false,()->removeSelected());remove.setTag("compose:remove");correct=ui.button("Corregir recorte",false,()->correctSelected());correct.setTag("compose:mask");ui.weighted(edits,remove,false);ui.weighted(edits,correct,true);ui.add(panel,edits,8);updateActions();

    }
    private void layers(){if(layerRow==null)return;layerRow.removeAllViews();addLayerChoice("Fondo","background");JSONArray layers=document.layers();for(int i=0;i<layers.length();i++)addLayerChoice("Producto "+(i+1),layers.optJSONObject(i).optString("id"));canvas.invalidate();updateActions();}
    private void updateActions(){if(remove==null||correct==null)return;boolean product=document.layer(canvas.selected)!=null;remove.setText(product?"Quitar producto":"Quitar fondo");remove.setEnabled(!busy);remove.setAlpha(!busy?1:.35f);correct.setEnabled(!busy&&product);correct.setAlpha(!busy&&product?1:.35f);}
    private void addLayerChoice(String name,String id){TextView choice=ui.button(name,false,()->{if(busy)return;canvas.selected=id;status.setText(id.equals("background")?"Arrastra el fondo · usa dos dedos para acercarlo":"Arrastra el producto · usa dos dedos para ajustar");layers();});choice.setMinHeight(ui.dp(40));choice.setTag("layer:"+id);choice.setSelected(canvas.selected.equals(id));choice.setBackground(ui.background(canvas.selected.equals(id)?PhotoUi.SURFACE:Color.TRANSPARENT,canvas.selected.equals(id)?PhotoUi.LIGHT:0,12));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-2,-2);params.rightMargin=ui.dp(6);layerRow.addView(choice,params);}
    private void markFormat(){for(String id:new String[]{"background","square","portrait","story"}){View choice=root.findViewWithTag("format:"+id);if(choice!=null)choice.setBackground(ui.background(document.state.optString("format").equals(id)?PhotoUi.SURFACE:Color.TRANSPARENT,0,10));}}
    private void commit(String before){try{document.save();if(!before.equals(document.state.toString())){history.add(before);if(history.size()>10)history.remove(0);}canvas.invalidate();markFormat();}catch(Exception error){try{document.state=new JSONObject(before);}catch(Exception ignored){}Toast.makeText(this,"No pudimos guardar el último cambio. La composición anterior se conserva.",Toast.LENGTH_LONG).show();canvas.invalidate();}}
    private void zoom(float factor){if(busy)return;String before=document.state.toString();try{document.zoom(canvas.selected,factor);commit(before);}catch(Exception error){status.setText("No pudimos cambiar el tamaño.");}}
    private void center(){if(busy)return;String before=document.state.toString();try{if(canvas.selected.equals("background"))document.state.put("bgX",0).put("bgY",0).put("bgScale",1);else{JSONObject layer=document.layer(canvas.selected);if(layer!=null)layer.put("x",.5).put("y",.5).put("scale",1);}commit(before);}catch(Exception error){status.setText("No pudimos centrar la imagen.");}}
    private void changeFormat(String format){if(busy)return;String before=document.state.toString();try{document.state.put("format",format);document.pan("background",0,0);commit(before);}catch(Exception error){status.setText("No pudimos cambiar el formato.");}}
    private void options(){if(busy)return;boolean product=document.layer(canvas.selected)!=null;String[] choices=product?new String[]{"Traer al frente","Formato de imagen","Deshacer último cambio"}:new String[]{"Formato de imagen","Deshacer último cambio"};new AlertDialog.Builder(this).setTitle(product?"Producto seleccionado":"Fondo").setItems(choices,(dialog,index)->{if(index==(product?2:1)){undo();return;}if(index==(product?1:0)){new AlertDialog.Builder(this).setTitle("Formato de imagen").setItems(new String[]{"Como el fondo","Cuadrado 1:1","Vertical 4:5","Historia 9:16"},(d,i)->changeFormat(new String[]{"background","square","portrait","story"}[i])).show();return;}String before=document.state.toString();JSONArray kept=new JSONArray();JSONObject selected=document.layer(canvas.selected);for(int i=0;i<document.layers().length();i++)if(!document.layers().optJSONObject(i).optString("id").equals(canvas.selected))kept.put(document.layers().optJSONObject(i));kept.put(selected);try{document.state.put("layers",kept);commit(before);layers();}catch(Exception error){status.setText("No pudimos cambiar el orden.");}}).setNegativeButton("Volver",null).show();}
    private void removeSelected(){if(busy)return;String before=document.state.toString();try{if(canvas.selected.equals("background")){Bitmap plain=Bitmap.createBitmap(960,960,Bitmap.Config.ARGB_8888);plain.eraseColor(0xfff3e5d3);document.replaceBackground(plain);plain.recycle();canvas.selected="background";commit(before);layers();status.setText("Fondo quitado · puedes elegir otro");return;}JSONArray kept=new JSONArray();for(int i=0;i<document.layers().length();i++)if(!document.layers().optJSONObject(i).optString("id").equals(canvas.selected))kept.put(document.layers().optJSONObject(i));document.state.put("layers",kept);canvas.selected=kept.length()==0?"background":kept.getJSONObject(kept.length()-1).getString("id");commit(before);layers();status.setText("Producto quitado · puedes deshacer desde Más");}catch(Exception error){status.setText("No pudimos quitar la selección. Tus imágenes se conservan.");}}
    private void correctSelected(){if(busy)return;JSONObject layer=document.layer(canvas.selected);if(layer==null)return;String id=canvas.selected;enabled(false);status.setText("Abriendo el recorte manual…");worker.execute(()->{try{MaskEditSession session=MaskEditSession.create(this,document.bitmap(layer.optString("source",layer.optString("file"))),document.bitmap(layer.optString("file")));runOnUiThread(()->{if(!destroyed){enabled(true);startActivityForResult(new Intent(this,MaskEditorActivity.class).putExtra("maskSessionId",session.id()).putExtra("layerId",id).putExtra("restoreLimited",!layer.has("source")),73);}});}catch(Exception|OutOfMemoryError error){runOnUiThread(()->{if(!destroyed){enabled(true);status.setText("No pudimos abrir el recorte. La imagen se conserva.");}});}});}
    private void undo(){if(history.isEmpty()){Toast.makeText(this,"No hay cambios por deshacer.",Toast.LENGTH_SHORT).show();return;}String before=document.state.toString(),previous=history.get(history.size()-1);try{document.state=new JSONObject(previous);document.save();history.remove(history.size()-1);if(!canvas.selected.equals("background")&&document.layer(canvas.selected)==null)canvas.selected="background";layers();markFormat();}catch(Exception error){try{document.state=new JSONObject(before);}catch(Exception ignored){}status.setText("No pudimos deshacer el cambio.");}}
    private void enabled(boolean value){busy=!value;canvas.setEnabled(value);save.setEnabled(value);save.setAlpha(value?1:.4f);enable(panel,value);updateActions();}
    private void enable(ViewGroup group,boolean value){for(int i=0;i<group.getChildCount();i++){View child=group.getChildAt(i);child.setEnabled(value);if(child instanceof ViewGroup)enable((ViewGroup)child,value);}}
    private void pick(boolean background){if(busy)return;if(!background&&document.layers().length()>=4){Toast.makeText(this,"Puedes combinar hasta 4 productos por imagen.",Toast.LENGTH_LONG).show();return;}try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE),background?71:72);}catch(Exception error){status.setText("No pudimos abrir la galería.");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==73){if(result==RESULT_OK&&data!=null){String id=data.getStringExtra("layerId"),sessionId=data.getStringExtra("maskSessionId");final String before=document.state.toString();enabled(false);status.setText("Aplicando el recorte…");worker.execute(()->{Bitmap corrected=null;try{corrected=MaskEditSession.open(this,sessionId).read("current.png");final String file=document.asset(corrected,"product");final JSONArray bounds=CompositionDocument.bounds(CompositionDocument.visibleBounds(corrected));runOnUiThread(()->{if(!destroyed){try{JSONObject layer=document.layer(id);if(layer!=null){layer.put("file",file).put("bounds",bounds);commit(before);}status.setText("Recorte corregido");}catch(Exception error){status.setText("No pudimos aplicar el recorte.");}enabled(true);}});}catch(Exception|OutOfMemoryError error){runOnUiThread(()->{if(!destroyed){enabled(true);status.setText("El recorte quedó vacío o no pudo guardarse. Conservamos el anterior.");}});}finally{if(corrected!=null)corrected.recycle();}});}return;}if(result!=RESULT_OK||data==null||data.getData()==null||(request!=71&&request!=72))return;Uri uri=data.getData();final String before=document.state.toString();enabled(false);status.setText(request==72?"Recortando el nuevo producto…":"Preparando tu fondo…");worker.execute(()->{Bitmap source=null,cutout=null,reference=null;FoodPhotoEngine engine=null;try{source=ImageTools.read(this,uri);final JSONObject layer;final String background;final int width=source.getWidth(),height=source.getHeight();if(request==72){engine=new FoodPhotoEngine(this,source);engine.includeObjects(true);cutout=engine.render(true,"transparent");reference=engine.render(true,"original");layer=document.prepareProduct(cutout,reference);background=null;}else{background=document.asset(source,"background");layer=null;}
            runOnUiThread(()->{if(destroyed)return;try{if(layer!=null){document.layers().put(layer);canvas.selected=layer.getString("id");}else{document.state.put("background",background).put("width",width).put("height",height).put("bgScale",1).put("bgX",0).put("bgY",0);canvas.selected="background";}commit(before);layers();status.setText(layer!=null?"Arrastra el nuevo producto para colocarlo":"Fondo listo · arrastra para encuadrar");}catch(Exception error){status.setText("No pudimos agregar la imagen.");}enabled(true);});
        }catch(Exception|OutOfMemoryError error){runOnUiThread(()->{if(!destroyed){enabled(true);status.setText("No pudimos agregar esa imagen. Tus productos se conservan.");Toast.makeText(this,error instanceof IOException?error.getMessage():"Prueba una imagen más pequeña.",Toast.LENGTH_LONG).show();}});}finally{if(engine!=null)engine.close();if(reference!=null)reference.recycle();if(cutout!=null)cutout.recycle();if(source!=null)source.recycle();}});}
    private void save(){if(busy)return;enabled(false);status.setText("Uniendo las imágenes…");worker.execute(()->{Bitmap image=null;android.util.AtomicFile file=new CrossFile(PhotoEditorActivity.output(this));FileOutputStream out=null;try{image=document.export();String encoded=ImageTools.encodeEdited(image);out=file.startWrite();out.write(encoded.getBytes("UTF-8"));file.finishWrite(out);runOnUiThread(()->{if(!destroyed){setResult(RESULT_OK,new Intent().putExtra("compositionId",document.id()));finish();}});}catch(Exception|OutOfMemoryError error){if(out!=null)file.failWrite(out);runOnUiThread(()->{if(!destroyed){enabled(true);status.setText("No pudimos guardar. Tu composición sigue aquí.");}});}finally{if(image!=null)image.recycle();}});}
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(canvas!=null){state.putString("selected",canvas.selected);state.putStringArrayList("history",history);}}
    @Override public void onDestroy(){destroyed=true;worker.execute(()->{if(document!=null)document.close();});worker.shutdown();super.onDestroy();}
}
